# shellcheck shell=bash

# lint-grafana-dashboards: shared lint for Grafana dashboard JSON (bead pg2-rkgr6e).
# Runs on SOURCE JSON for static dashboards and on RENDERED artifacts for
# generated ones (host-metrics.json carries @guard@ placeholders; daemon-health
# is generated by Nix). PUSHED_GAUGES_FILE is injected by the builder (tests
# export it themselves when driving the raw source).

show_help() {
  cat <<'HELP'
lint-grafana-dashboards: lint Grafana dashboard JSON files

Usage: lint-grafana-dashboards [--error L1] [--list L1] DASHBOARD.json...

Rules (failure lines read RULE-Ln: FILE: PANEL TITLE):
  L1  a query target with a literal window such as [5m] (a WARNING unless
      --error L1; opt out per panel with "window: fixed" in its description;
      windows inside last_over_time(...) and $__rate_interval etc. do not count)
  L2  per-process labels in by(...) or legendFormat, a sum/avg/count straight
      over a pushed gauge, or a bare pushed-gauge selector
  L3  two panels with one title, or a row title containing $
  L4  a panel with an empty or missing title
  L5  a stat panel with a non-instant rate/irate/increase target

L2 to L5 are errors always. Without --error L1 the L1 findings print one
"WARN L1: N targets with fixed windows" line and the exit status stays 0.

Options:
  --error L1     treat L1 findings as errors (exit 1)
  --list L1      print "FILE | PANEL ID | PANEL TITLE | EXPR" per unmarked literal
                 window and nothing else; nothing when clean; exit 0
  -h, --help     Show this help message
  -v, --version  Show version information

Exit status: 0 clean (or L1 warnings only), 1 a rule failed or a file is not
valid JSON, 2 usage error.
HELP
}

die() {
  echo "error: $1" >&2
  exit "${2:-2}"
}

LINT_JQ=$(
  cat <<'JQ'
def win: "\\[[0-9]+(ms|s|m|h|d|w)(:[0-9a-z]*)?\\]";
def labels: "instance|pid|service_version|service_instance_id|process_runtime_version|host_name";
def l2a: "by\\s*\\([^)]*\\b(" + labels + ")\\b";
def l2leg: "\\{\\{ ?(" + labels + ") ?\\}\\}";
def l2b: "\\b(sum|avg|count)(\\s+by\\s*\\([^)]*\\))?\\s*\\(\\s*(" + $g + ")\\b";
def l2c: "^\\s*(" + $g + ")(\\{[^}]*\\})?\\s*$";
def panels: [.. | objects | select((.type | type) == "string" and (.gridPos | type) == "object")];
def targets: (.targets // [])[] | select(type == "object");
def rec($r; $p; $e): [$r, ($p.id // "" | tostring), ($p.title // ""), ($e | gsub("[\\t\\n]"; " "))] | join("\t");
panels as $ps
| (
    ($ps[] | . as $p | select(((.description // "") | contains("window: fixed")) | not)
      | targets | select((.expr // "") | gsub("last_over_time\\([^()]*\\[[^\\]]*\\]\\)"; "") | test(win))
      | rec("L1"; $p; .expr)),
    ($ps[] | . as $p | targets
      | select(((.expr // "") | (test(l2a) or test(l2b) or test(l2c))) or ((.legendFormat // "") | test(l2leg)))
      | rec("L2"; $p; .expr // "")),
    ([$ps[] | select(.type != "row" and ((.title // "") != ""))] | group_by(.title)[]
      | select(length > 1) | .[0] as $p | rec("L3"; $p; "")),
    ($ps[] | select(.type == "row" and ((.title // "") | contains("$"))) | . as $p | rec("L3"; $p; "")),
    ($ps[] | select(.type != "row" and ((.title // "") == "")) | . as $p | rec("L4"; $p; "")),
    ($ps[] | select(.type == "stat") | . as $p | targets
      | select(.instant != true and ((.expr // "") | test("\\b(rate|irate|increase)\\(")))
      | rec("L5"; $p; .expr))
  )
JQ
)

ERROR_L1=false
LIST_L1=false
FILES=()

while [[ $# -gt 0 ]]; do
  case $1 in
  -h | --help)
    show_help
    exit 0
    ;;
  --error)
    [[ ${2:-} == L1 ]] || die "--error only accepts L1"
    ERROR_L1=true
    shift
    ;;
  --list)
    [[ ${2:-} == L1 ]] || die "--list only accepts L1"
    LIST_L1=true
    shift
    ;;
  --)
    shift
    FILES+=("$@")
    break
    ;;
  -*) die "Unknown option: $1" ;;
  *) FILES+=("$1") ;;
  esac
  shift
done

[[ ${#FILES[@]} -gt 0 ]] || die "no dashboard files given (try --help)"
[[ -r ${PUSHED_GAUGES_FILE:-} ]] || die "PUSHED_GAUGES_FILE is not readable: ${PUSHED_GAUGES_FILE:-unset}"

GAUGES=$(rg -v '^\s*(#|$)' "$PUSHED_GAUGES_FILE" | paste -sd'|' -)
[[ -n $GAUGES ]] || die "no families in $PUSHED_GAUGES_FILE"

status=0
l1_count=0
for file in "${FILES[@]}"; do
  [[ -r $file ]] || die "cannot read $file"
  if ! records=$(jq -r --arg g "$GAUGES" "$LINT_JQ" "$file" 2>/dev/null); then
    echo "error: $file: not valid dashboard JSON" >&2
    status=1
    continue
  fi
  while IFS=$'\t' read -r rule id title expr; do
    [[ -n $rule ]] || continue
    if [[ $rule == L1 ]]; then
      l1_count=$((l1_count + 1))
      if $LIST_L1; then
        echo "$file | $id | $title | $expr"
      elif $ERROR_L1; then
        echo "RULE-L1: $file: $title"
        status=1
      fi
    elif ! $LIST_L1; then
      [[ -n $title ]] || title="(untitled panel id $id)"
      echo "RULE-$rule: $file: $title"
      status=1
    fi
  done <<<"$records"
done

if $LIST_L1; then
  exit 0
fi
if [[ $l1_count -gt 0 ]] && ! $ERROR_L1; then
  echo "WARN L1: $l1_count targets with fixed windows" >&2
fi
exit "$status"
